const LANG = {
  SINGULAR: 'result',
  PLURAL: 'results',
  POSTS_RESET: 'posts_reset',
  POSTS_UPDATED: 'posts_updated',
}

const count = () => {
  return getPosts().length
}

const displayCount = (elementSelector, resultCount) => {
  const element = document.querySelector(elementSelector)
  if (!element) return

  const text = resultCount > 1 ? `${resultCount} ${LANG.PLURAL}` : `${resultCount} ${LANG.SINGULAR}`

  element.textContent = text
}

const getPosts = () => {
  return Array.from(document.querySelectorAll('.post-card')).filter(post => post.style.display !== 'none')
}

const getAllPosts = () => {
  return Array.from(document.querySelectorAll('.post-card'))
}

const updateCount = () => {
  const postNumber = count()
  displayCount('.filter--results p', postNumber)
}

const getSelectedTags = filterInputs => {
  return Array.from(filterInputs)
    .filter(filterInput => {
      const input = filterInput.querySelector('input')
      return input && input.checked
    })
    .map(filterInput => filterInput.querySelector('input').value)
}

const updateResults = filterInputs => {
  const tags = getSelectedTags(filterInputs)
  const posts = getAllPosts()

  if (tags.length === 0) {
    reset(filterInputs)
    return LANG.POSTS_RESET
  }

  const matchedPosts = posts.filter(post => {
    const postTags = (post.getAttribute('resource-tags') || '').split(',')
    return tags.some(tag => postTags.includes(tag))
  })

  for (const post of posts) {
    post.style.setProperty('display', matchedPosts.includes(post) ? 'block' : 'none', 'important')
  }

  checkIfBlank()
  updateCount()
  return LANG.POSTS_UPDATED
}

const reset = filterInputs => {
  const posts = getAllPosts()

  for (const post of posts) {
    post.style.setProperty('display', 'block', 'important')
  }

  for (const filterInput of filterInputs) {
    const input = filterInput.querySelector('input')
    if (input) input.checked = false
  }

  checkIfBlank()
  updateCount()
}

const checkIfBlank = () => {
  const blankSlate = document.querySelector('.blankslate')
  const visiblePosts = getPosts()

  if (blankSlate) {
    blankSlate.style.display = visiblePosts.length === 0 ? 'block' : 'none'
  }
}

const toggleLayout = layout => {
  const posts = getAllPosts()

  for (const post of posts) {
    post.classList.remove('list', 'stack')
    post.classList.add(layout)
  }
}

const getQueryString = filterInputs => {
  const urlParams = new URLSearchParams(window.location.search)
  const filters = urlParams.get('filters')

  if (filters) {
    const tags = filters.split('&')
    for (const tag of tags) {
      const matchingInput = Array.from(filterInputs).find(input => input.querySelector('input').value === tag)
      if (matchingInput) {
        matchingInput.querySelector('input').checked = true
      }
    }
    updateResults(filterInputs)
  }
}

document.addEventListener('DOMContentLoaded', () => {
  const categoryHeaders = document.querySelectorAll('.filter--category-label')
  for (const header of categoryHeaders) {
    header.addEventListener('click', () => {
      const categoryContainer = header.closest('.filter--category')
      categoryContainer.classList.toggle('is-active')
    })
  }

  const filterInputs = document.querySelectorAll('.filter--input')
  for (const filterInput of filterInputs) {
    const input = filterInput.querySelector('input')
    input.addEventListener('change', () => updateResults(filterInputs))
  }

  const clearLinks = document.querySelectorAll('.clear-filters')
  for (const link of clearLinks) {
    link.addEventListener('click', e => {
      e.preventDefault()
      reset(filterInputs)
    })
  }

  const layoutToggles = document.querySelectorAll('.btn-list')
  for (const toggle of layoutToggles) {
    toggle.addEventListener('click', e => {
      for (const t of layoutToggles) {
        t.classList.remove('active')
      }
      const btn = e.currentTarget
      btn.classList.add('active')

      const layout = btn.classList.contains('list') ? 'list' : 'stack'
      toggleLayout(layout)
    })
  }

  updateCount()
  getQueryString(filterInputs)
})
